import{_ as n,C as r,o,c as d,E as a,a4 as i}from"./chunks/framework.BMj-uaUw.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么第一节课不讲代码","slug":"为什么第一节课不讲代码","link":"#为什么第一节课不讲代码","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit01/index.md","filePath":"unit01/index.md","lastUpdated":1789356894000}'),l={name:"unit01/index.md"};function s(u,t,h,g,c,p){const e=r("UnitMeta");return o(),d("div",null,[a(e,{unit:"单元 1",title:"工程化认知、学习路线与开发环境",module:"模块一 · 工程化认知与工具链",hours:"4 学时",week:"第 1 周",goals:["能说出前端工程化要解决的六类问题","能描述一个现代前端项目的标准目录结构","能画出个人的前端学习路线图并标注当前所处位置","能独立完成开发环境搭建并通过自检"],outcomes:["环境自检报告","个人学习路线图"]}),t[0]||(t[0]=i('<h2 id="为什么第一节课不讲代码" tabindex="-1">为什么第一节课不讲代码 <a class="header-anchor" href="#为什么第一节课不讲代码" aria-label="Permalink to &quot;为什么第一节课不讲代码&quot;">​</a></h2><p>先看一段真实对话。学生问：&quot;老师，为什么我写的页面在别人电脑上打不开？&quot; 答案通常是&quot;你少装了个包&quot;或者&quot;你 Node 版本不对&quot;。学生接着问：&quot;那我怎么知道他需要什么？&quot; —— 问题就出在这里：<strong>他不知道一个前端工程到底需要哪些东西才能跑起来。</strong></p><p>这就是工程化要解决的第一类问题：<strong>让一个项目在任何一台干净机器上都能按同样的方式跑起来。</strong></p><p>所以这门课第一节课不写业务代码，而是先回答三个问题：</p><ol><li>前端是怎么从&quot;一个 HTML 文件&quot;变成&quot;一套工程&quot;的？</li><li>工程化到底在解决哪些问题？（六类，后面每个单元都会对上其中某一类）</li><li>我需要什么环境，怎么确认环境是好的？</li></ol><div class="tip custom-block"><p class="custom-block-title">一句话概括这个单元的作用</p><p><strong>先看清全局，再动手。</strong> 知道每个工具是为什么存在的，后面学配置的时候才不会背命令。</p></div><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit01/01-why-engineering.html">1.1 前端是怎么走到工程化的</a></td><td>从静态页面到组件化的四个阶段，每一步被什么痛点推动</td><td>为什么需要这些东西</td></tr><tr><td><a href="/frontend-engineering-course/unit01/02-modern-project.html">1.2 一个现代前端工程长什么样</a></td><td>目录结构、配置文件的作用、三条脚本命令的含义</td><td>这些东西分别放在哪、干什么用</td></tr><tr><td><a href="/frontend-engineering-course/unit01/03-learning-path.html">1.3 学习路线与岗位方向</a></td><td>三阶段路线、五个岗位方向、本课程覆盖范围</td><td>我现在在哪一站，下一站做什么</td></tr><tr><td><a href="/frontend-engineering-course/unit01/04-environment.html">1.4 开发环境搭建与自检</a></td><td>Node、包管理器、编辑器、浏览器、Git 逐项安装与验证</td><td>怎么把环境弄干净</td></tr><tr><td><a href="/frontend-engineering-course/unit01/ai-collaboration.html">AI 协作 · 让 AI 帮你调研与排错</a></td><td>用 AI 解释概念、读报错、列环境清单；它编造包名与命令时怎么核实</td><td>借力之前先知道它哪里不可靠</td></tr></tbody></table><p>四节之间是递进关系：先知道<strong>为什么</strong>（1.1），再知道<strong>长什么样</strong>（1.2）， 然后知道<strong>自己在哪</strong>（1.3），最后<strong>把工具装好</strong>（1.4）。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：工程化解决哪六类问题？你有没有在别人电脑上跑不起来项目的经历？</td></tr><tr><td>讲解</td><td>1.3 学时</td><td>重点讲 1.1 的发展脉络与 1.2 的目录结构；1.3 与 1.4 以自学 + 现场答疑为主</td></tr><tr><td>现场任务</td><td>1.8 学时</td><td>按清单完成环境搭建并截图留证；画出自己的学习路线图</td></tr><tr><td>复盘</td><td>0.6 学时</td><td>展示两三份路线图，对比不同同学对自己的定位判断</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易出问题的环节</p><p>环境搭建看起来简单，实际上是全课程<strong>最容易卡住的环节之一</strong> —— Node 装不上、pnpm 装完不生效、 Windows PowerShell 禁止执行脚本，都会在这里遇到。</p><p>建议：<strong>装之前先通读 <a href="/frontend-engineering-course/unit01/04-environment.html">1.4</a>，装的时候每步都跑一遍验证命令。</strong> 不要一口气装完再回头验证 —— 一旦某一步错了，后面全部跟着错，排查成本翻倍。</p></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>这个单元不需要任何前端基础，但需要三样东西：</p><ul><li><strong>一台能装软件的电脑</strong>：Windows 10 以上、macOS 12 以上都可以，8 GB 内存以上。</li><li><strong>能上网</strong>：下载 Node 与依赖需要网络。如果宿舍网络不稳，可以先用手机热点把 Node 装好。</li><li><strong>一个记录工具</strong>：记事本、Notion、Markdown 文件都行。环境搭建过程中会遇到各种报错和解决办法， 记下来。<strong>这一次记的东西，会在这门课里反复用上。</strong></li></ul><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p>按课程要求，这次课要交两样东西：</p><p><strong>一、环境自检报告</strong></p><p>不是截图堆砌，而是一份能用文字说明&quot;我的环境是什么状态&quot;的记录。至少包含：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>版本信息</td><td>Node、npm、pnpm、Git 各自的版本号</td></tr><tr><td>安装方式</td><td>用的是什么工具装的（fnm / nvm / 直接安装包）</td></tr><tr><td>遇到的问题</td><td>至少写一条：遇到什么报错、怎么解决的</td></tr><tr><td>自检结果</td><td><a href="/frontend-engineering-course/unit01/04-environment.html">1.4 末尾的清单</a>逐项打勾的情况</td></tr></tbody></table><p><strong>二、个人学习路线图</strong></p><p>用一页纸说明三件事：</p><ol><li>你在<a href="/frontend-engineering-course/guide/learning-path.html">三阶段路线</a>的哪一站（打地基 / 上装备 / 定方向）。</li><li>哪些能力项你已经过关，哪些还不行 —— <strong>判断标准是&quot;能不能独立做出来&quot;，不是&quot;看没看过教程&quot;</strong>。</li><li>这门课结束后，你想往哪个方向继续深入（业务开发 / 跨端 / 服务端渲染 / 质量与工程 / 可视化）。</li></ol><details class="details custom-block"><summary>一份合格的路线图长什么样</summary><p>去年有位同学的路线图是这样的（节选）：</p><blockquote><p>当前位置：<strong>第一阶段末尾</strong>。 已过关：HTML 结构、CSS 布局（能不看资料做响应式）、JS 基础语法与数组方法。 未过关：Promise 只看得懂不会写；没碰过 Git；不知道 package.json 是什么。 本课程目标：把工具链和 Vue 补上，能独立交付一个带登录的项目。 之后方向：跨端开发，想往小程序方向走，准备寒假学 uni-app。</p></blockquote><p><strong>注意它的特点</strong>：诚实、具体、有可验证的标准（&quot;只看得懂不会写&quot;没算过关）。 最没用的写法是&quot;HTML 熟练、CSS 熟练、JS 熟练&quot; —— 这种既不诚实也没法指导下一步。</p></details><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>这个单元是整门课的&quot;地图&quot;，不涉及具体技术细节。读完直接进入 <a href="/frontend-engineering-course/unit02/">单元 2：Node 生态与构建工具</a>，那里开始真刀真枪配东西。</p><p>如果想先补充整体认知，可以顺带看看：</p><ul><li><a href="/frontend-engineering-course/guide/learning-path.html">前端学习路线</a> —— 比 1.3 更完整的版本</li><li><a href="/frontend-engineering-course/guide/roadmap.html">12 周课程地图</a> —— 整门课的节奏</li><li><a href="/frontend-engineering-course/guide/how-to-use.html">怎么用这套教程</a> —— 教程的阅读约定</li></ul>',28))])}const q=n(l,[["render",s]]);export{f as __pageData,q as default};
